Proceso MayorDeUnaSerie
    Definir cantidad Como Entero;
    Definir i Como Entero;
    Definir valor Como Entero;
    Definir mayor Como Entero;
    Leer cantidad;
    Leer mayor;
    Para i <- 2 Hasta cantidad Hacer
        Leer valor;
        Si valor > mayor Entonces
            mayor <- valor;
        FinSi
    FinPara
    Escribir mayor;
FinProceso
